/* N3 shares the existing study archive, audio, favorites and cloud document. */
const n3Unit=id=>N3_UNITS.find(u=>u.id===id);
const n3State=u=>state.n3.units[u.id]??={done:[],ratings:[],answers:{},review:{},draft:''};
const n3Next=()=>N3_UNITS.find(u=>!n3State(u).done.includes('review'));
const n3Ids=u=>[...u.grammarIds,...u.reading.ids,...u.listening.ids];
const n3FinalIds=()=>N3_UNITS.flatMap((u,i)=>[u.grammarIds[i%2],u[i%2?'reading':'listening'].ids[0]]);
const n3Pct=()=>Math.round(N3_UNITS.reduce((n,u)=>n+n3State(u).done.length,0)/120*100);
const n3Score=(ids,map)=>Math.round(ids.filter(id=>map[id]===questionById(id).answer).length/ids.length*100);
let n3FinalOpen=false,n3Guided=false;
function n3CanFinish(u,k){const s=n3State(u);if(k==='words')return u.wordIds.every(id=>s.ratings.includes(id));const ids=k==='grammar'?u.grammarIds:k==='review'?n3Ids(u):u[k].ids,map=k==='review'?s.review:s.answers;return ids.every(id=>Number.isInteger(map[id]))&&(k!=='review'||N3_STAGES.slice(0,4).every(k=>s.done.includes(k))&&n3Score(ids,map)>=80);}
function n3Paint(){const open=[...document.querySelectorAll('[data-n3detail][open]')].map(x=>x.dataset.n3detail),top=window.scrollY;render(false);for(const el of document.querySelectorAll('[data-n3detail]'))if(open.includes(el.dataset.n3detail))el.open=true;window.scrollTo({top,behavior:'instant'});}
function n3Question(id,map,kind){const q=questionById(id),a=map[id],answered=Number.isInteger(a),final=kind==='final';return `<article class="n5-question" id="n3q-${id}"><h3>${esc(q.q)}</h3><div class="answers">${q.options.map((o,i)=>`<button data-n3answer="${id}" data-kind="${kind}" data-value="${i}" ${answered&&!final?'disabled':''} ${final?`aria-pressed="${a===i}"`:''} class="${final?(a===i?'selected':''):answered&&i===q.answer?'correct':answered&&a===i?'wrong':''}">${esc(o)}</button>`).join('')}</div>${answered&&!final?`<p class="feedback" role="status">${a===q.answer?'✓ 正确':'✕ 再理解一次'} · ${esc(q.why)}</p>`:''}</article>`;}
function n3Text(u,kind,map,mode='answers'){const t=u[kind],audio=kind==='listening';return `<article class="n5-text"><h2>${esc(u.title)} · ${N3_STAGE_LABELS[kind]}</h2>${audio?`<button class="primary" data-speak="${esc(t.text)}">▷ 播放对话</button><details data-n3detail="${u.id}-${kind}-text"><summary>听后查看原文</summary><p class="japanese-text" lang="ja">${esc(t.text)}</p></details>`:`<p class="japanese-text" lang="ja">${esc(t.text)}</p>`}<details data-n3detail="${u.id}-${kind}-translation"><summary>中文对照</summary><p>${esc(t.translation)}</p></details>${t.ids.map(id=>n3Question(id,map,mode)).join('')}</article>`;}
function n3Daily(){if(state.n3.day)return state.n3.day;const u=n3Next();if(!u)return null;const stages=N3_STAGES.filter(k=>!n3State(u).done.includes(k)).slice(0,state.plan.minutes===20?1:state.plan.minutes===60?3:2);state.n3.day={unit:u.id,stages};persist();return state.n3.day;}
function n3DailyHtml(home=false){const d=n3Daily();if(!d)return `<section class="container page-section"><h2>24 个 N3 单元已通过</h2><button class="primary" id="n3Final">进行结课测评 →</button><button class="secondary" data-page="favorites">复习收藏</button></section>`;const u=n3Unit(d.unit),s=n3State(u),all=d.stages.every(k=>s.done.includes(k)),active=d.stages.find(k=>!s.done.includes(k));return `<section class="container page-section"><div class="dash-section-head"><h2>今日 N3 学习</h2><span>第 ${state.n3.number} 学习日 · ${state.plan.minutes} 分钟</span></div><h3>第 ${N3_UNITS.indexOf(u)+1} 单元 · ${esc(u.title)}</h3><div class="dash-task-list">${d.stages.map((k,i)=>`<button class="dash-task ${s.done.includes(k)?'is-done':k===active?'is-current':'is-pending'}" data-n3daily="${k}" ${!all&&k!==active&&!s.done.includes(k)?'disabled':''}><span class="dash-task-number">${s.done.includes(k)?'✓':i+1}</span><strong>${N3_STAGE_LABELS[k]}</strong></button>`).join('')}</div><div class="toolbar">${all?'<button class="primary" id="n3NextDay">开始下一学习日 →</button>':''}${!home?'<button class="secondary" id="n3Budget">调整每日时间</button><button class="secondary" id="n3Overview">全部 N3 课程</button>':''}</div></section>`;}
function n3Overview(){const next=n3Next();return title('','N3 系统课程','')+`<section class="container page-section"><div class="n5-course-hero"><div><h2>从句子走向段落</h2><p>24 单元 · 48 节句型 · 240 条单元词汇 · 48 篇读听材料</p><div class="toolbar">${next?`<button class="primary" data-n3unit="${next.id}">继续第 ${N3_UNITS.indexOf(next)+1} 单元 →</button>`:''}<button class="secondary" id="n3UsePlan">加入每日计划</button><button class="secondary" id="n3Final">结课测评</button></div></div><div><b>${n3Pct()}%</b><p>${N3_UNITS.filter(u=>n3State(u).done.includes('review')).length}/24 单元通过</p></div></div><details class="learning-help"><summary>课程范围与学习方式</summary><p>原创 N3 教学选编，前几单元复习 N4 衔接表达，逐步练习时间、条件、推断、立场与篇章理解。每节含接续、易错点、两组例句；每篇阅读与听力各三题。单元词汇含跨单元复现，并非 240 个全新词或官方完整考纲。听力使用合成语音，建议搭配官方真人材料。完成前四步、单元复习至少答对 7/8 题后通过。</p><a href="https://www.jlpt.jp/e/about/levelsummary.html" target="_blank" rel="noopener">JLPT 官方能力说明 ↗</a></details>${N3_MODULES.map((name,m)=>`<div class="sectionhead"><h2>${m+1}. ${esc(name)}</h2><button class="secondary" data-n3focus="${m}">本模块专项练习 →</button></div><div class="n5-unit-grid">${N3_UNITS.filter(u=>u.module===m).map(u=>{const s=n3State(u),started=s.done.length||s.ratings.length||Object.keys(s.answers).length,passed=s.done.includes('review');return `<button class="n5-unit-card ${passed?'n3-passed':started?'n3-started':''}" data-n3unit="${u.id}"><span class="label">第 ${N3_UNITS.indexOf(u)+1} 单元</span><span class="n5-badge">${passed?'✓ 已通过':started?'◐ 学习中':'○ 未开始'}</span><h3>${esc(u.title)}</h3><div class="bar"><div style="width:${s.done.length/5*100}%"></div></div><span>${s.done.length}/5 步骤 · ${u.grammar.map(g=>esc(g.title)).join(' / ')}</span></button>`;}).join('')}</div>`).join('')}</section>`;}
function n3UnitHtml(u){const s=n3State(u),k=state.n3.stage;let body='';
 if(k==='words')body=`<div class="n5-word-grid">${u.wordIds.map(id=>{const w=words.find(w=>w.id===id);return `<article class="n5-word" data-word-id="${id}"><span class="n5-badge">${s.ratings.includes(id)?'✓ 已自评':'○ 待认读'}</span><h3 lang="ja">${esc(w.word)}</h3>${n4Favorite('word:'+id)}<details data-expand-reading="${esc(w.reading)}"><summary>展开读音与词义</summary><p lang="ja">${esc(w.reading)}</p>${romanLine(w.reading)}<p class="vocab-meaning"><span>词义</span> <strong>${esc(w.meaning)}</strong></p><p><span>词性</span> <span class="pos-badge">${esc(w.pos)}</span></p><button class="secondary" data-speak="${esc(w.reading)}">▷ 听读音</button><div class="toolbar"><button class="secondary" data-n3rate="${id}" data-value="0">还不熟</button><button class="primary" data-n3rate="${id}" data-value="1">记住了 ✓</button></div></details></article>`;}).join('')}</div>`;
 if(k==='grammar')body=u.grammar.map(g=>`<article class="n5-grammar"><h2>${esc(g.title)}</h2>${n4Favorite('grammar:'+g.id)}<p>${esc(g.rule)}</p>${g.examples.map(([ja,kana,zh],i)=>`<div class="example"><b lang="ja">${esc(ja)}</b><p lang="ja">${esc(kana)}</p>${romanLine(kana,true)}<p>${esc(zh)}</p><button class="secondary" data-speak="${esc(ja)}">▷ 跟读</button>${n4Favorite('example:'+g.id+':'+i)}</div>`).join('')}<div class="hint">易错点：${esc(g.pitfall)}</div>${n3Question(g.id,s.answers,'answers')}</article>`).join('');
 if(k==='reading'||k==='listening')body=n3Text(u,k,s.answers);
 if(k==='review')body='<p>8 题 · 至少答对 7 题，并完成前四步后通过。</p>'+u.grammarIds.map(id=>n3Question(id,s.review,'review')).join('')+n3Text(u,'reading',s.review,'review')+n3Text(u,'listening',s.review,'review');
 return title('','N3 · '+u.title,'')+`<section class="container page-section"><div class="toolbar"><button class="secondary" id="n3Overview">← 全部单元</button><button data-page="plan" data-level="N3" class="secondary">每日计划</button><span>第 ${N3_UNITS.indexOf(u)+1}/24 单元</span></div><div class="n5-stage-tabs" role="group" aria-label="单元步骤">${N3_STAGES.map((st,i)=>`<button data-n3stage="${st}" aria-pressed="${st===k}" class="${st===k?'selected':''}">${s.done.includes(st)?'✓':i+1} ${N3_STAGE_LABELS[st]}</button>`).join('')}</div>${body}<div class="n5-finish"><p id="n3FinishStatus" role="status">${s.done.includes(k)?'✓ 本步已完成':n3CanFinish(u,k)?'可以完成本步了':k==='review'?'先完成前四步，并达到 80%':'完成本步全部自评或作答后继续'}</p><button class="primary" id="n3Finish" ${!n3CanFinish(u,k)?'disabled':''}>${k==='review'?'通过单元，继续 →':'完成本步，继续 →'}</button>${k!=='words'?'<button class="secondary" id="n3Retry">重做本步练习</button>':''}</div><details class="writing-panel" data-n3detail="${u.id}-writing"><summary>可选写作 · 用两个句型写一段话</summary><textarea id="n3Draft" maxlength="4000" aria-label="单元写作草稿">${esc(s.draft)}</textarea><p id="n3DraftStatus" role="status">草稿自动保存</p><details><summary>写作提示与参考</summary><p>用「${esc(u.grammar[0].title)}」和「${esc(u.grammar[1].title)}」描述自己经历的一件事，再补充原因或结果。</p>${u.grammar.map(g=>`<p lang="ja">${esc(g.examples[1][0])}</p><p>${esc(g.examples[1][2])}</p>`).join('')}<p>检查接续、前后逻辑、时态与助词；参考句不代表唯一答案。</p></details></details></section>`;
}
function n3FinalHtml(){const f=state.n3.final,ids=n3FinalIds(),answered=ids.filter(id=>Number.isInteger(f.answers[id])).length;return title('','N3 结课测评','')+`<section class="container page-section"><button class="secondary" id="n3Overview">← 全部单元</button><p>48 题 · 已答 ${answered}/48 · 可离开后继续作答</p>${f.submitted?`<h2>正确率 ${n3Score(ids,f.answers)}%</h2><button class="secondary" id="n3ResetFinal">开始新一轮测评</button>`:'<p>交卷后统一显示答案与解析；交卷前可以修改选择。</p>'}${ids.map((id,i)=>{const q=questionById(id);return `<section class="n3-exam-item"><span class="label">${i+1}/48 · ${typeNames[q.type]}</span>${q.text?(q.type==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放听力</button>${f.submitted?`<p class="japanese-text" lang="ja">${esc(q.text)}</p>`:''}`:`<p class="japanese-text" lang="ja">${esc(q.text)}</p>`):''}${f.submitted?`<h3>${esc(q.q)}</h3><p>${f.answers[id]===q.answer?'✓ 正确':'✕ 答错'} · 你的选择：${esc(q.options[f.answers[id]])}</p><div class="hint">答案：${esc(q.options[q.answer])}<p>${esc(q.why)}</p></div>`:n3Question(id,f.answers,'final')}</section>`;}).join('')}${!f.submitted?`<button class="primary" id="n3SubmitFinal" ${answered<ids.length?'disabled':''}>交卷并查看解析</button>`:''}</section>`;}
const n3PreviousLessons=renderLessons;renderLessons=function(isGrammar=false){return level==='N3'&&!isGrammar?n3FinalOpen?n3FinalHtml():state.n3.cursor?n3UnitHtml(n3Unit(state.n3.cursor)):n3Overview():n3PreviousLessons(isGrammar);};
const n3PreviousPlan=renderPlan;renderPlan=function(){return level==='N3'?title('','N3 每日计划','')+n3DailyHtml():n3PreviousPlan();};
const n3PreviousProgress=dashboardProgress;dashboardProgress=function(l){return l==='N3'?n3Pct():n3PreviousProgress(l);};
const n3PreviousHome=renderHome;renderHome=function(){let html=n3PreviousHome().replace('N3</strong><span>核心练习','N3</strong><span>系统课程');if(level==='N3'){const u=n3Unit(state.n3.cursor)||n3Next()||N3_UNITS.at(-1);if(!state.activeQuiz)html=html.replace(esc(nextGrammar('N3').title),esc(u.title)).replace(`data-lesson="${nextGrammar('N3').id}"`,`data-n3unit="${u.id}"`).replace('核心练习进度','单元步骤进度');html=html.replace(/<section class="container dash-today">[\s\S]*?<\/section>/,n3DailyHtml(true));}return html;};
const n3PreviousTexts=renderTexts;renderTexts=function(kind){if(level!=='N3')return n3PreviousTexts(kind);return title('',kind==='reading'?'N3 阅读训练':'N3 听力训练','')+`<section class="container page-section"><p>24 个主题 · 每篇 3 题</p><div class="n5-unit-grid">${N3_UNITS.map((u,i)=>`<button class="n5-unit-card" data-n3unit="${u.id}" data-n3open="${kind}"><span class="label">第 ${i+1} 单元</span><span class="n5-badge">${n3State(u).done.includes(kind)?'✓ 已完成':'○ 待学习'}</span><h3>${esc(u.title)}</h3><span>打开课文与练习 →</span></button>`).join('')}</div><details class="learning-help"><summary>原有核心训练篇章</summary>${(kind==='reading'?readings:listenings).filter(q=>q.level==='N3'&&!q.unit).map(q=>`<article class="text-card"><h3>${esc(q.title)}</h3>${kind==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放</button>`:''}<p class="japanese-text">${esc(q.text)}</p>${answerBlock(q)}<button class="secondary" data-textdone="${q.id}" disabled>完成并记录</button></article>`).join('')}</details></section>`;};
const n3PreviousArchive=renderProgress;renderProgress=function(){return n3PreviousArchive()+`<section class="container page-section"><h2>N3 系统课程</h2><p>${N3_UNITS.filter(u=>n3State(u).done.includes('review')).length}/24 单元通过 · ${n3Pct()}% 步骤完成${state.n3.final.submitted?' · 结课 '+n3Score(n3FinalIds(),state.n3.final.answers)+'%':''}</p><button class="primary" data-n3unit="${(n3Next()||N3_UNITS.at(-1)).id}">继续 N3 →</button></section>`;};
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
 if(d.n3unit){const u=n3Unit(d.n3unit);if(!u)return;state.n3.cursor=u.id;state.n3.stage=N3_STAGES.includes(d.n3open)?d.n3open:N3_STAGES.find(k=>!n3State(u).done.includes(k))||'review';n3FinalOpen=false;n3Guided=false;persist();go('lessons','N3');render();}
 if(d.n3stage&&N3_STAGES.includes(d.n3stage)){state.n3.stage=d.n3stage;persist();render();}
 if(d.n3daily){const day=n3Daily();if(!day||!day.stages.includes(d.n3daily))return;const s=n3State(n3Unit(day.unit)),active=day.stages.find(k=>!s.done.includes(k));if(active&&d.n3daily!==active&&!s.done.includes(d.n3daily))return;state.n3.cursor=day.unit;state.n3.stage=d.n3daily;n3FinalOpen=false;n3Guided=true;persist();go('lessons','N3');render();}
 if(b.id==='n3Overview'){state.n3.cursor=null;n3FinalOpen=false;n3Guided=false;persist();go('lessons','N3');render();}
 if(b.id==='n3UsePlan'){state.plan.start='N3';if(LEVELS.indexOf(state.plan.target)<LEVELS.indexOf('N3'))state.plan.target='N3';persist();go('plan','N3');render();}
 if(b.id==='n3Budget'){const vals=[20,40,60];state.plan.minutes=vals[(vals.indexOf(state.plan.minutes)+1)%3];persist();n3Paint();toast('每天 '+state.plan.minutes+' 分钟，下个学习日生效。');}
 if(b.id==='n3NextDay'){const day=n3Daily();if(day&&day.stages.every(k=>n3State(n3Unit(day.unit)).done.includes(k))){state.n3.day=null;state.n3.number++;persist();render(false);}}
 if(d.n3answer){const q=questionById(d.n3answer),a=Number(d.value),u=n3Unit(state.n3.cursor),final=d.kind==='final';if(!q||!Number.isInteger(a)||!q.options[a])return;if(final){if(state.n3.final.submitted||!n3FinalIds().includes(q.id))return;}else if(!u||!['answers','review'].includes(d.kind)||!n3Ids(u).includes(q.id))return;const map=final?state.n3.final.answers:n3State(u)[d.kind];if(!final&&map[q.id]!==undefined)return;map[q.id]=a;if(!final)recordAnswer(q,a);persist();n3Paint();}
 if(d.n3rate){const u=n3Unit(state.n3.cursor);if(!u?.wordIds.includes(d.n3rate))return;const s=n3State(u);s.ratings=[...new Set([...s.ratings,d.n3rate])];const old=state.wordReviews[d.n3rate],box=d.value==='1'?old?.last===dateKey()?Math.max(old.box,1):Math.min((old?.box||0)+1,6):0;state.wordReviews[d.n3rate]={box,due:box?afterDays([1,3,7,14,30,60][box-1]):dateKey(),last:dateKey()};touch('vocab');persist();b.textContent=d.value==='1'?'✓ 已记住':'↺ 待巩固';const badge=b.closest?.('[data-word-id]')?.querySelector('.n5-badge');if(badge)badge.textContent='✓ 已自评';$('#n3Finish').disabled=!n3CanFinish(u,'words');$('#n3FinishStatus').textContent=n3CanFinish(u,'words')?'可以完成本步了':'已自评 '+s.ratings.length+'/'+u.wordIds.length+' 个';}
 if(b.id==='n3Finish'){const u=n3Unit(state.n3.cursor),k=state.n3.stage;if(!u||!n3CanFinish(u,k))return;const s=n3State(u);if(!s.done.includes(k)){s.done.push(k);if(k==='grammar')u.grammarIds.forEach(markLesson);if(k==='reading'||k==='listening')state.textDone=[...new Set([...state.textDone,...u[k].ids])];touch(k==='words'?'vocab':k==='review'?'practice':k);}const next=N3_STAGES[N3_STAGES.indexOf(k)+1];if(next)state.n3.stage=next;else state.n3.cursor=null;persist();if(n3Guided)go('plan','N3');render();toast(k==='review'?'✓ 单元通过，记录已保存。':'本步已保存。');}
 if(b.id==='n3Retry'){const u=n3Unit(state.n3.cursor),k=state.n3.stage;if(!u||k==='words')return;for(const id of k==='grammar'?u.grammarIds:k==='review'?n3Ids(u):u[k].ids)delete(k==='review'?n3State(u).review:n3State(u).answers)[id];persist();render(false);}
 if(d.n3focus!==undefined){if(state.activeQuiz){go('practice',state.activeQuiz.level);toast('先完成或结束当前练习。');return;}const m=Number(d.n3focus);if(!Number.isInteger(m)||m<0||m>3)return;const ids=N3_UNITS.filter(u=>u.module===m).flatMap((u,i)=>[u.grammarIds[i%2],u[i%2?'reading':'listening'].ids[1]]);guideActive=false;state.activeQuiz={level:'N3',mode:'exam',ids:shuffled(ids),answers:[],index:0};persist();go('practice','N3');render();}
 if(b.id==='n3Final'){n3FinalOpen=true;n3Guided=false;go('lessons','N3');render();}
 if(b.id==='n3SubmitFinal'){const f=state.n3.final;if(f.submitted||!n3FinalIds().every(id=>Number.isInteger(f.answers[id])))return;f.submitted=true;const sections=Object.fromEntries(['grammar','vocab','reading','listening'].map(k=>[k,{correct:0,total:0}]));for(const id of n3FinalIds()){const q=questionById(id);sections[q.type].total++;if(recordAnswer(q,f.answers[id]))sections[q.type].correct++;}state.history.push({date:dateKey(),level:'N3',score:n3Score(n3FinalIds(),f.answers),total:48,sections});state.history=state.history.slice(-100);persist();render();}
 if(b.id==='n3ResetFinal'){state.n3.final={answers:{},submitted:false};persist();render();}
});
document.addEventListener('input',e=>{if(e.target.id==='n3Draft'){const u=n3Unit(state.n3.cursor);if(!u)return;n3State(u).draft=e.target.value.slice(0,4000);persist();$('#n3DraftStatus').textContent='✓ 草稿已保存';}});
render(false);
